pub fn utf8IndexAtWidthExcludeANSI(input_: []const u8, max_width: usize) usize {
            var input = input_;
            _ = &input;
            var w: usize = 0;
            _ = &w;
            while (strings.indexOfCharUsize(input, 27)) |esc| {
                const run_start = (@intFromPtr(input.ptr) - @intFromPtr(input_.ptr));
                if (utf8WalkRun(input_, run_start, esc, max_width, (&w))) |stop| {
                    _ = &stop;
                    return stop;
                }
                input = input[esc..];
                if ((input.len < 2)) {
                    return input_.len;
                }
                if ((input[1] == 91)) {
                    if ((input.len < 3)) {
                        return input_.len;
                    }
                    input = input[2..];
                    if (scanLaneInRange(u8, 64, 126, input)) |t| {
                        _ = &t;
                        input = input[(t + 1)..];
                    } else {
                        return input_.len;
                    }
                } else {
                    if ((input[1] == 93)) {
                        input = input[2..];
                        while (true) {
                            if (scanLaneAnyOf(u8, (&osc_terms_u8), input)) |t| {
                                _ = &t;
                                const term = input[@as(usize, @intCast(t))];
                                if (((term == 7) or (term == 156))) {
                                    input = input[(t + 1)..];
                                    break;
                                }
                                if ((((t + 1) < input.len) and (input[@as(usize, @intCast((t + 1)))] == 92))) {
                                    input = input[(t + 2)..];
                                    break;
                                }
                                input = input[(t + 1)..];
                            } else {
                                input = input[input.len..];
                                break;
                            }
                        }
                    } else {
                        input = input[1..];
                    }
                }
            }
            const run_start = (@intFromPtr(input.ptr) - @intFromPtr(input_.ptr));
            if (utf8WalkRun(input_, run_start, input.len, max_width, (&w))) |stop| {
                _ = &stop;
                return stop;
            }
            return input_.len;
    }

pub fn utf8WalkRun(input: []const u8, start: usize, len: usize, max_width: usize, w: *usize) ?usize {
            {
                var bytes = input[start..(start + len)];
                _ = &bytes;
                while (firstNonASCII(bytes)) |i| {
                    var k: usize = 0;
                    _ = &k;
                    while ((k < i)) : (k = (k + 1)) {
                        const cw: usize = (if (comptime @typeInfo(@TypeOf(visibleLatin1WidthScalar(bytes[@as(usize, @intCast(k))]))) == .@"enum") cp_cast_int(usize, @intFromEnum(visibleLatin1WidthScalar(bytes[@as(usize, @intCast(k))]))) else cp_cast_int(usize, visibleLatin1WidthScalar(bytes[@as(usize, @intCast(k))])));
                        if (((w.* + cw) > max_width)) {
                            return ((@intFromPtr(bytes.ptr) - @intFromPtr(input.ptr)) + k);
                        }
                        w.* = (w.* + cw);
                    }
                    const this_chunk = bytes[i..];
                    const byte = this_chunk[0];
                    const skip = bun.strings.wtf8ByteSequenceLengthWithInvalid(byte);
                    const avail = @min((if (comptime @typeInfo(@TypeOf(skip)) == .@"enum") cp_cast_int(usize, @intFromEnum(skip)) else cp_cast_int(usize, skip)), this_chunk.len);
                    const cp_bytes: [4]u8 = .{ byte, (if ((avail > 1)) this_chunk[1] else 0), (if ((avail > 2)) this_chunk[2] else 0), (if ((avail > 3)) this_chunk[3] else 0) };
                    const cp = (if ((skip > 1)) decodeWTF8RuneTMultibyte((&cp_bytes), skip, u32, unicode_replacement) else unicode_replacement);
                    const cw: usize = (if (comptime @typeInfo(@TypeOf(visibleCodepointWidth(cp, false))) == .@"enum") cp_cast_int(usize, @intFromEnum(visibleCodepointWidth(cp, false))) else cp_cast_int(usize, visibleCodepointWidth(cp, false)));
                    if (((w.* + cw) > max_width)) {
                        return ((@intFromPtr(bytes.ptr) - @intFromPtr(input.ptr)) + i);
                    }
                    w.* = (w.* + cw);
                    bytes = bytes[@min((i + skip), bytes.len)..];
                }
                var k: usize = 0;
                _ = &k;
                while ((k < bytes.len)) : (k = (k + 1)) {
                    const cw: usize = (if (comptime @typeInfo(@TypeOf(visibleLatin1WidthScalar(bytes[@as(usize, @intCast(k))]))) == .@"enum") cp_cast_int(usize, @intFromEnum(visibleLatin1WidthScalar(bytes[@as(usize, @intCast(k))]))) else cp_cast_int(usize, visibleLatin1WidthScalar(bytes[@as(usize, @intCast(k))])));
                    if (((w.* + cw) > max_width)) {
                        return ((@intFromPtr(bytes.ptr) - @intFromPtr(input.ptr)) + k);
                    }
                    w.* = (w.* + cw);
                }
                return null;
            }
    }
